mapper.select:
SELECT b.FINPROD_ID AS finprodId,
A.VALUE_DATE AS valueDate, A.CLOSE_PRICE AS closePrice, A.AVERAGE_PRICE AS averagePrice, A.MAX_PRICE AS maxPrice, A.MIN_PRICE AS minPrice, A.BUY_ONE_PRICE AS buyOnePrice, A.SELL_ONE_PRICE AS sellOnePrice, B.FINPROD_ABBR AS fundName, C.TYPE_1 AS fundType FROM mst_FUND_MARKET_INFO A LEFT JOIN FIN_PRODUCT B ON B.FINPROD_MARKET_ID = A.FUND_CODE LEFT JOIN FIN_PRODUCT_TYPE C ON C.FINPROD_ID = B.FINPROD_ID AND B.FINPROD_TYPE = #{finprodType} WHERE 1=1
AND b.FINPROD_TYPE = #{finprodType}
AND b.FINPROD_ID LIKE concat_ws('', '%', #{fundCode} ,'%')
AND A.VALUE_DATE < = #{endDate}
AND A.VALUE_DATE > = #{startDate}
AND C.TYPE_1 = #{fundType}
AND B.FINPROD_ABBR LIKE concat_ws('', '%', #{fundName} ,'%')
